// ─── Configuración ────────────────────────────────────────────────────────
// Rellena estos valores, o defínelos como variables de entorno de n8n. Ojo: por
// defecto n8n bloquea $env dentro de los nodos Code
// (N8N_BLOCK_ENV_ACCESS_IN_NODE); si no la desactivas, se usan los de aquí.
//
// IG_USER_ID es el id de tu cuenta de Instagram Business/Creator, no el @usuario:
//   GET /{page-id}?fields=instagram_business_account
const AJUSTES = {
  IG_USER_ID: 'PON_AQUI_TU_IG_USER_ID',
  GRAPH_API_VERSION: 'v25.0',
  GRAPH_API_HOST: 'https://graph.facebook.com',
};

const env = (() => { try { return $env ?? {}; } catch { return {}; } })();
const IG_USER_ID = env.IG_USER_ID || AJUSTES.IG_USER_ID;
const VERSION = env.GRAPH_API_VERSION || AJUSTES.GRAPH_API_VERSION;
const HOST = env.GRAPH_API_HOST || AJUSTES.GRAPH_API_HOST;

if (IG_USER_ID === 'PON_AQUI_TU_IG_USER_ID') {
  throw new Error('Falta IG_USER_ID: rellénalo en el nodo Configuración o define la variable de entorno.');
}

// Rango pedido por el panel: 7d | 30d | 90d | 12m
const RANGE_DAYS = { '7d': 7, '30d': 30, '90d': 90, '12m': 365 };
const range = $input.first().json.query?.range ?? '30d';
const days = RANGE_DAYS[range] ?? 30;

const until = Math.floor(Date.now() / 1000);
const since = until - days * 86400;

// ⚠ Los nombres de métrica cambian entre versiones de la Graph API. Si alguna
// deja de existir, Meta devuelve error y el panel mostrará "—" en ese KPI.
// Revísalos contra la versión que uses antes de dar el dato por bueno.
const METRICS = ['reach', 'total_interactions', 'follower_count', 'website_clicks'];

return [{ json: {
  igUserId: IG_USER_ID,
  version: VERSION,
  host: HOST,
  range, days, since, until,
  metrics: METRICS.join(','),
} }];

// Une el perfil y las métricas en la forma que espera el panel.
const cfg = $('Configuración').first().json;
const profile = $('Perfil').first().json ?? {};
const insights = $('Insights de cuenta').first().json ?? {};

// La Graph API responde { data: [{ name, total_value: { value } }] } y, si algo
// falla, { error: { message } }. Se tolera cualquiera de las dos.
const byName = {};
for (const row of insights.data ?? []) {
  byName[row.name] = row.total_value?.value ?? row.values?.[0]?.value ?? null;
}

const reach = byName.reach ?? null;
const interactions = byName.total_interactions ?? null;
const engagement = reach && interactions ? (interactions / reach) * 100 : null;

// El sandbox de n8n puede no traer ICU completo, así que toLocaleString no
// agrupa: el separador de miles se pone a mano.
const miles = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

const fmt = (n) => (n == null ? null
  : n >= 1e6 ? (n / 1e6).toFixed(2) + 'M'
  : n >= 1e3 ? (n / 1e3).toFixed(1) + 'K'
  : String(n));

const captions = { '7d': 'vs semana anterior', '30d': 'vs mes anterior',
                   '90d': 'vs trimestre anterior', '12m': 'vs año anterior' };

return [{ json: {
  source: 'instagram',
  range: cfg.range,
  errors: [insights.error?.message, profile.error?.message].filter(Boolean),
  account: {
    name: profile.name ?? null,
    handle: profile.username ? '@' + profile.username : null,
    followers: fmt(profile.followers_count),
    posts: profile.media_count ?? null,
    avatar: profile.profile_picture_url ?? null,
  },
  kpis: {
    alcance: { value: fmt(reach), caption: captions[cfg.range] },
    engagement: { value: engagement == null ? null : engagement.toFixed(1) + '%', caption: 'interacciones / alcance' },
    seguidores: { value: byName.follower_count == null ? null : '+' + miles(byName.follower_count), caption: 'en el periodo' },
    clicks: { value: byName.website_clicks == null ? null : miles(byName.website_clicks), caption: 'clicks en el enlace del perfil' },
  },
} }];
